{"python":"rows = get_rows('article.xml','Table 2.')

truth_by_drug = {
    'Sotalol': 1,
    'Dofetilide': 1,
    'Quinidine': 1,
    'Cisapride': 1,
    'Terfenadine': 1,
    'Ranolazine': 1,
    'Mexiletine': 0,
    'Nifedipine': 0,
    'Verapamil': 0,
    'Alfuzosin': 0,
    'Aspirin': 0,
    'DMSO': 0,
}

records = []
for r in [4, 5, 6, 7, 8, 10, 12, 13, 14, 15, 16, 17]:
    row = rows[r - 1]
    drug = str(row[1]).strip()
    mid_value = str(row[3]).strip()
    prediction = 1 if mid_value.startswith('↑') else 0
    records.append({
        'id': drug,
        'score': {
            'ref': f'article.xml/Table 2./R{r}C4',
            'map': {mid_value: prediction}
        },
        'truth': {
            'ref': f'article.xml/Table 2./R{r}C2',
            'map': {drug: truth_by_drug[drug]}
        }
    })

assert len(records) == 12
assert sum(1 for rec in records if rec['score']['map'][list(rec['score']['map'])[0]] == rec['truth']['map'][list(rec['truth']['map'])[0]]) == 11

CONTRACT = {
